package com.weaponsregistration.reconciliation.controller;
import com.weaponsregistration.reconciliation.dto.InventoryCountContract.*;import com.weaponsregistration.reconciliation.service.InventoryCountService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/erp/inventory-counts") public class InventoryCountController{private final InventoryCountService service;public InventoryCountController(InventoryCountService service){this.service=service;}@PostMapping public CountView open(@RequestBody OpenRequest r){return service.open(r);}@PutMapping("/{id}/count") public CountView count(@PathVariable long id,@RequestBody SubmitRequest r){return service.count(id,r);}@PostMapping("/{id}/approve") public CountView approve(@PathVariable long id){return service.approve(id);}@PostMapping("/{id}/cancel") public CountView cancel(@PathVariable long id){return service.cancel(id);}@GetMapping public Page<CountView> list(@RequestParam long organizationId,@RequestParam(required=false)Long unitId,@RequestParam(defaultValue="0")int page){return service.list(organizationId,unitId,page);}}
